\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Medical AI Conference Color Theme ──
% Deep navy primary, steel blue secondary, amber accent for risks
\definecolor{primary}{HTML}{1E3A5F}     % deep navy
\definecolor{secondary}{HTML}{2E7D8C}  % steel blue/teal
\definecolor{accent}{HTML}{D97706}       % amber for risk highlights
\definecolor{danger}{HTML}{C2410C}      % coral-red for risk callouts
\definecolor{bgposter}{HTML}{F0F5F7}    % cool off-white background
\definecolor{textdark}{HTML}{1E293B}
\definecolor{textgray}{HTML}{475569}
\definecolor{cardred}{HTML}{FEF2F2}     % warm tint for risk cards
\definecolor{cardblue}{HTML}{F0F9FF}    % cool tint for applications
\definecolor{cardgreen}{HTML}{F0FDF4}    % tint for framework
\definecolor{cardcream}{HTML}{FFFBEB}   % tint for overview
\definecolor{redtitlebg}{HTML}{FEE2E2}
\definecolor{bluetitlebg}{HTML}{E0F2FE}
\definecolor{greentitlebg}{HTML}{DCFCE7}
\definecolor{creamtitlegbg}{HTML}{FEF3C7}
\definecolor{stathighlight}{HTML}{FEF3C7}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardred,
    borderline west={5pt}{0pt}{danger},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{danger},
    coltitle=danger, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={danger!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardblue,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardcream,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=creamtitlegbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardgreen,
    borderline west={5pt}{0pt}{059669},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color}{059669},
    coltitle=059669, colbacktitle=greentitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={059669!50},
    valign=top, drop shadow={opacity=0.15},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries Large Language Models in Medicine}\\[10pt]
  {\fontsize{32}{40}\selectfont Opportunities, Risks, and the Path Forward}\\[10pt]
  {\fontsize{26}{32}\selectfont\color{white!80} Medical AI \& Digital Health Conference 2024}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} >90\%}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} GPT-4 USMLE Score}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} All 3 steps passed}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} 500+}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} PubMed Articles}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} Published in 2023}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{danger!50}{cardred}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{danger} 30\%}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Hallucination Rate}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} Medical Q\&A outputs}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} \$10.5B}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Health LLM Market}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} Projected 2030}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══ ROW A: OVERVIEW + APPLICATIONS ══
\posterbox[darkcard, title={What Are LLMs?}]
{name=overview, column=1, between=row6 and row11}{
  \fontsize{30}{38}\selectfont
  \textbf{Foundation models} trained on vast text corpora capable of understanding and generating medical language.\\[6pt]
  Key examples: GPT-4, Med-PaLM 2, LLaMA.\\[8pt]
  \colorbox{primary!15}{\parbox{0.92\linewidth}{%
    \centering\fontsize{24}{30}\selectfont\color{primary}
    Rapid emergence: 500+ papers in 2023 alone
  }}
}

\posterbox[bluecard, title={Key Clinical Applications}]
{name=applications, column=2, between=row6 and row11}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}
    \item \textbf{Clinical Documentation} — automated notes, discharge summaries
    \item \textbf{Diagnostic Support} — differential diagnosis, radiology
    \item \textbf{Patient Communication} — Q\&A, jargon simplification
    \item \textbf{Medical Education} — exam prep, case-based learning
    \item \textbf{Biomedical Research} — literature synthesis, protocol drafting
  \end{itemize}
}

\posterbox[bluecard, title={Fastest Adoption}]
{name=adoption, column=3, between=row6 and row11}{
  \fontsize{30}{38}\selectfont
  Clinical documentation and patient communication tools have seen the fastest real-world deployment.\\[6pt]
  Several health systems now integrate LLM-powered assistants into EHR systems.\\[8pt]
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\color{secondary}
    Market projected to reach \$10.5B by 2030
  }}
}

% ══ ROW B: PERFORMANCE + RISKS ══
\posterbox[darkcard, title={Performance Benchmarks}]
{name=performance, column=1, between=row11 and row16}{
  \fontsize{30}{38}\selectfont
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{48}{58}\selectfont\bfseries\color{primary} >90\%}\\[3pt]
    {\fontsize{22}{28}\selectfont GPT-4 on USMLE}\\[2pt]
    {\fontsize{18}{22}\selectfont\color{textgray} All 3 steps — far exceeds 60\% pass threshold}\\[4pt]
    \vspace{2pt}%
  }}
  \vspace{4pt}
  \begin{itemize}
    \item \textbf{Med-PaLM 2:} 86.5\% on MedQA benchmark
    \item \textbf{GPT-3.5:} Near 60\% threshold
    \item Performance on real-world scenarios remains less characterized
  \end{itemize}
}

\posterbox[redcard, title={Risks, Limitations \& Ethics}]
{name=risks, column=2, between=row11 and row16}{
  \fontsize{30}{38}\selectfont
  \begin{itemize}
    \item \textbf{Hallucinations} — fabricated citations, inaccurate info (up to 30\%)
    \item \textbf{Bias \& Equity} — model perpetuates training data disparities
    \item \textbf{Privacy} — patient data transmitted to external servers
    \item \textbf{Lack of Validation} — mostly MCQ benchmarks, not clinical trials
    \item \textbf{Over-reliance Risk} — automation bias in clinicians
  \end{itemize}
}

\posterbox[redcard, title={Critical Gap}]
{name=gap, column=3, between=row11 and row16}{
  \fontsize{30}{38}\selectfont
  \colorbox{danger!15}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{36}{44}\selectfont\bfseries\color{danger} Benchmark ≠ Deployment}\\[6pt]
    {\fontsize{22}{28}\selectfont\color{textdark} Impressive scores do not guarantee safe clinical use}\\[4pt]
    \vspace{2pt}%
  }}
  \vspace{6pt}
  \fontsize{28}{34}\selectfont
  The gap between benchmark performance and real-world safety is significant.
}

% ══ ROW C: FRAMEWORK ══
\posterbox[greencard, title={Framework for Responsible Deployment}]
{name=framework, column=1, span=3, between=row16 and bottom}{
  \fontsize{30}{38}\selectfont
  \begin{tabular}{p{0.28\linewidth}p{0.28\linewidth}p{0.28\linewidth}}
    \begin{itemize}
      \item \textbf{Rigorous Evaluation} in diverse clinical settings
      \item \textbf{Human-in-the-Loop} clinician oversight of all outputs
    \end{itemize} &
    \begin{itemize}
      \item \textbf{Transparent Reporting} of limitations \& failure modes
      \item \textbf{Equity Audits} across patient populations
    \end{itemize} &
    \begin{itemize}
      \item \textbf{Regulatory Alignment} with FDA, EMA, WHO guidance
      \item Evidence-based deployment before clinical integration
    \end{itemize}
  \end{tabular}
  \vspace{4pt}
  \colorbox{059669!15}{\parbox{0.96\linewidth}{%
    \centering\fontsize{24}{30}\selectfont\color{059669}
    LLMs hold transformative potential — but deployment must be guided by evidence, equity, and robust governance to ensure patient safety.
  }}
}

\end{tcbposter}
\end{document}

